package mx.com.mesaregia.logistica.api.controller; import mx.com.mesaregia.logistica.application.service.LogisticaCancellationService; import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/internal/v1/logistica") @ConditionalOnProperty(prefix="mesaregia.internal-endpoints",name="enabled",havingValue="true") public class InternalLogisticaController {private final LogisticaCancellationService s;public InternalLogisticaController(LogisticaCancellationService s){this.s=s;} @PostMapping("/ordenes/{idOrden}/cancelar") @PreAuthorize("isAuthenticated()") public void cancelar(@PathVariable Long idOrden){s.cancelarPorOrden(idOrden);} }
